import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_lines_busiest_first_with_one_decimal(self):
        shifts = [
            make_shift("Ana", "mon", 8, 12),
            make_shift("Ben", "mon", 8, 16),
            make_shift("Ana", "tue", 8, 11),
            make_shift("Cy", "wed", 9, 10),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ben: 1 shifts, 8.0 hours",
                "Ana: 2 shifts, 7.0 hours",
                "Cy: 1 shifts, 1.0 hours",
            ],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        shifts = [make_shift("Ana", "mon", 8, 12), make_shift("  ", "tue", 8, 12)]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)


if __name__ == "__main__":
    unittest.main()
